#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
using namespace std;

int main(){
vector<double> gradient={2,-2,4,0,1,-1,3,-3};
double mean=0,variance=0;
for(double g:gradient)mean+=g/gradient.size();
for(double g:gradient)variance+=pow(g-mean,2)/gradient.size();
double variancePairMean=0;
for(int i=0;i<int(gradient.size());i+=2){
    double batch=(gradient[i]+gradient[i+1])/2;
    variancePairMean+=pow(batch-mean,2)/(gradient.size()/2);
}
cout<<"Single variance "<<variance<<" pair-batch variance "<<variancePairMean<<endl;
    return 0;
}

