#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
using namespace std;

int main(){
vector<int> label={0,0,1,1,1,0};
double p=0;for(int y:label)p+=y/double(label.size());
double parent=2*p*(1-p);
for(int cut:{2,3,4}){
    int leftOnes=0,rightOnes=0;
    for(int i=0;i<int(label.size());i++){
        if(i<cut)leftOnes+=label[i];
        else rightOnes+=label[i];
    }
    double pl=double(leftOnes)/cut;
    double pr=double(rightOnes)/(label.size()-cut);
    double weighted=cut/double(label.size())*2*pl*(1-pl)
        +(label.size()-cut)/double(label.size())*2*pr*(1-pr);
    cout<<"Cut "<<cut<<" Gini reduction "<<parent-weighted<<endl;
}
    return 0;
}

