#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
using namespace std;

int main(){
vector<double> x={-1,0,1,3};
double prior[2]={0.4,0.6},mean[2]={0,2};
double sigma[2]={1,1};
for(double value:x){
    double score[2],largest=-1e100;
    for(int k=0;k<2;k++){
        double z=(value-mean[k])/sigma[k];
        score[k]=log(prior[k])-log(sigma[k])-z*z/2;
        largest=max(largest,score[k]);
    }
    double denominator=exp(score[0]-largest)+exp(score[1]-largest);
    cout<<value<<" "<<exp(score[0]-largest)/denominator
        <<" "<<exp(score[1]-largest)/denominator<<endl;
}
    return 0;
}

