#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
using namespace std;

int main(){
vector<double> token={1,2,3,4};
for(int t=0;t<int(token.size());t++){
    vector<double> score(token.size(),-1e100);
    for(int j=0;j<=t;j++)score[j]=token[t]*token[j]/sqrt(2.0);
    double peak=*max_element(score.begin(),score.end()),sum=0;
    for(int j=0;j<=t;j++)sum+=exp(score[j]-peak);
    double total=0;
    for(int j=0;j<=t;j++)total+=exp(score[j]-peak)/sum;
    cout<<t<<" visible "<<t+1<<" probability sum "<<total<<endl;
}
    return 0;
}

