#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
using namespace std;

int main(){
vector<int> correct={1,1,0,1,0};
vector<double> features={1,2,-1,1,-2};
double weight=0,rate=0.2;
for(int epoch=0;epoch<80;epoch++){
    double gradient=0;
    for(int i=0;i<int(correct.size());i++){
        double probability=1/(1+exp(-weight*features[i]));
        gradient+=(probability-correct[i])*features[i]/correct.size();
    }
    weight-=rate*gradient;
}
cout<<"Fitted supervised classifier weight "<<weight<<endl;
    return 0;
}

